// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type LivingNetworkProps = Record<string, any>;

const LivingNetwork: React.FC<LivingNetworkProps> = ({
  backgroundColor = "#071712",
  transparentBackground = false,
  durationInSeconds = 8,
  primaryColor = "#55ffcc",
  level1Color = "#1f7a55",
  level2Color = "#334d40",
  lineColor = "#1a4030",
  centralLabel = "GR",
  typewriterText = "Establishing secure connection to Malloy Studio...",
  networkData = [
    { label: "IE", children: ["RB"] },
    { label: "NR", children: ["NK"] },
    { label: "GA", children: ["TH"] },
    { label: "SD", children: ["BL", "WC"] },
    { label: "JH", children: ["ML", "CR"] },
    { label: "DP", children: ["SP"] },
  ]
}) => {

  useFontLoader(["Inter", "Poppins"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const { nodes, edges, totalL1, totalL2 } = useMemo(() => {
    const n: any[] = [];
    const e: any[] = [];
    
    const cx = width / 2;
    const cy = height / 2;
    const r1 = Math.min(width, height) * 0.28;
    const r2 = Math.min(width, height) * 0.16;

    // Root node
    n.push({ id: 'root', label: centralLabel, level: 0, x: cx, y: cy, appearFrame: 10 });
    
    let currentFrame = 25; 
    const branchStagger = 15; 
    const childStagger = 5; 

    const numL1 = networkData.length;
    let l2Count = 0;
    
    networkData.forEach((l1Node, i) => {
        // Start roughly at top but slightly offset for a more organic look
        const angle1 = (i / numL1) * Math.PI * 2 - Math.PI / 2 + 0.3; 
        const x1 = cx + r1 * Math.cos(angle1);
        const y1 = cy + r1 * Math.sin(angle1);
        const l1Id = `l1-${i}`;
        
        const l1AppearFrame = currentFrame;
        const l1NodeAppearFrame = l1AppearFrame + 10;
        
        n.push({ id: l1Id, label: l1Node.label, level: 1, x: x1, y: y1, appearFrame: l1NodeAppearFrame });
        e.push({ id: `e-${l1Id}`, start: {x: cx, y: cy}, end: {x: x1, y: y1}, appearFrame: l1AppearFrame, level: 1 });
        
        let childFrame = l1NodeAppearFrame + 5;
        const numL2 = l1Node.children.length;
        l2Count += numL2;
        const spreadAngle = Math.PI / 1.5; 
        
        l1Node.children.forEach((l2Label, j) => {
            let angle2 = angle1;
            if (numL2 > 1) {
                angle2 = angle1 - spreadAngle / 2 + (j / (numL2 - 1)) * spreadAngle;
            }
            
            const x2 = x1 + r2 * Math.cos(angle2);
            const y2 = y1 + r2 * Math.sin(angle2);
            const l2Id = `l2-${i}-${j}`;
            
            const l2EdgeAppearFrame = childFrame;
            const l2NodeAppearFrame = l2EdgeAppearFrame + 10;
            
            n.push({ id: l2Id, label: l2Label, level: 2, x: x2, y: y2, appearFrame: l2NodeAppearFrame });
            e.push({ id: `e-${l2Id}`, start: {x: x1, y: y1}, end: {x: x2, y: y2}, appearFrame: l2EdgeAppearFrame, level: 2 });
            
            childFrame += childStagger;
        });
        
        currentFrame += branchStagger;
    });
    
    return { nodes: n, edges: e, totalL1: numL1, totalL2: l2Count };
  }, [networkData, centralLabel, width, height]);

  // Typewriter logic
  const typewriterEndFrame = 10 + Math.max(typewriterText.length, 1) * 2;
  const typewriterLength = Math.floor(
    interpolate(
      frame,
      [10, typewriterEndFrame],
      [0, typewriterText.length],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
    )
  );
  
  const currentTypewriterText = typewriterText.slice(0, typewriterLength);
  const cursorOpacity = Math.floor(frame / 15) % 2 === 0 ? 1 : 0;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", overflow: 'hidden' }}>
      
      {/* Subtle background glow */}
      <div style={{
        position: 'absolute',
        inset: 0,
        background: `radial-gradient(circle at center, rgba(255,255,255,0.03) 0%, rgba(0,0,0,0.6) 100%)`,
        pointerEvents: 'none',
        transition: 'none'
      }} />

      {/* Edges Layer */}
      <svg style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', overflow: 'visible', transition: 'none' }}>
        {edges.map((edge) => {
          const drawProgress = interpolate(
            frame,
            [edge.appearFrame, edge.appearFrame + 12],
            [0, 1],
            { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
          );
          
          const currentX2 = interpolate(drawProgress, [0, 1], [edge.start.x, edge.end.x]);
          const currentY2 = interpolate(drawProgress, [0, 1], [edge.start.y, edge.end.y]);
          const lineOpacity = frame >= edge.appearFrame ? 1 : 0;

          return (
            <line
              key={edge.id}
              x1={edge.start.x}
              y1={edge.start.y}
              x2={currentX2}
              y2={currentY2}
              stroke={lineColor}
              strokeWidth={edge.level === 1 ? 3 : 2}
              opacity={lineOpacity}
              strokeLinecap="round"
              style={{ transition: 'none' }}
            />
          );
        })}
      </svg>

      {/* Nodes Layer */}
      {nodes.map((node) => {
        const scale = spring({
          frame: frame - node.appearFrame,
          fps,
          config: { damping: 14, mass: 0.8 }
        });

        const nodeOpacity = interpolate(
          frame,
          [node.appearFrame, node.appearFrame + 5],
          [0, 1],
          { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
        );

        const size = node.level === 0 ? width * 0.07 : node.level === 1 ? width * 0.045 : width * 0.035;
        const fontSize = node.level === 0 ? 28 : node.level === 1 ? 18 : 14;
        const color = node.level === 0 ? primaryColor : node.level === 1 ? level1Color : level2Color;
        const bg = node.level === 0 ? '#0d2b20' : node.level === 1 ? '#0a1f17' : '#07140f'; 

        return (
          <div
            key={node.id}
            style={{
              position: 'absolute',
              left: node.x,
              top: node.y,
              width: size,
              height: size,
              borderRadius: '50%',
              backgroundColor: bg,
              border: `2px solid ${color}`,
              display: 'flex',
              justifyContent: 'center',
              alignItems: 'center',
              color: node.level === 0 ? '#ffffff' : '#dddddd',
              fontSize,
              fontWeight: 700,
              transform: `translate(-50%, -50%) scale(${scale})`,
              opacity: nodeOpacity,
              boxShadow: node.level === 0 ? `0 0 40px ${color}66, inset 0 0 20px ${color}33` : 'none',
              zIndex: 10 - node.level,
              transition: 'none'
            }}
          >
            {node.label}
          </div>
        );
      })}

      {/* Legend */}
      <div style={{
        position: 'absolute',
        bottom: '40px',
        left: '40px',
        display: 'flex',
        gap: '30px',
        padding: '20px 30px',
        backgroundColor: 'rgba(0,0,0,0.4)',
        borderRadius: '16px',
        border: '1px solid rgba(255,255,255,0.05)',
        backdropFilter: 'blur(10px)',
        transition: 'none'
      }}>
        {[
          { color: primaryColor, label: "You" },
          { color: level1Color, label: `1st Level (${totalL1})` },
          { color: level2Color, label: `2nd Level (${totalL2})` }
        ].map((item, i) => {
          const legendOpacity = interpolate(
            frame, 
            [100 + i * 10, 115 + i * 10], 
            [0, 1], 
            { extrapolateRight: 'clamp', extrapolateLeft: 'clamp' }
          );
          
          return (
            <div key={item.label} style={{ display: 'flex', alignItems: 'center', gap: '12px', opacity: legendOpacity, transition: 'none' }}>
              <div style={{ 
                width: '12px', 
                height: '12px', 
                borderRadius: '50%', 
                backgroundColor: item.color, 
                boxShadow: `0 0 10px ${item.color}80`,
                transition: 'none'
              }} />
              <span style={{ color: '#ccc', fontSize: '16px', fontWeight: 600, transition: 'none' }}>{item.label}</span>
            </div>
          )
        })}
      </div>

      {/* Typewriter Overlay */}
      <div style={{
        position: 'absolute',
        bottom: '40px',
        right: '40px',
        fontFamily: "Poppins",
        color: primaryColor,
        fontSize: '18px',
        fontWeight: 400,
        display: 'flex',
        alignItems: 'center',
        backgroundColor: 'rgba(0,0,0,0.4)',
        padding: '20px 30px',
        borderRadius: '16px',
        border: '1px solid rgba(255,255,255,0.05)',
        backdropFilter: 'blur(10px)',
        opacity: frame > 5 ? 1 : 0,
        transition: 'none'
      }}>
        <span style={{ transition: 'none' }}>{currentTypewriterText}</span>
        <span style={{
          opacity: cursorOpacity,
          marginLeft: '6px',
          width: '10px',
          height: '20px',
          backgroundColor: primaryColor,
          display: 'inline-block',
          boxShadow: `0 0 8px ${primaryColor}80`,
          transition: 'none'
        }} />
      </div>

    </AbsoluteFill>
  );
};

export default LivingNetwork;